const $=s=>document.querySelector(s);
const source='https://github.com/pustka-sh/Relay';
const external=(url,label,cls='')=>`<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const code=(value,label='terminal')=>`<div class="code-block"><div class="code-label"><span>${label}</span><button class="copy-button" type="button">Copy</button></div><pre><code>${esc(value)}</code></pre></div>`;
const callout=(text)=>`<aside class="callout"><p>${text}</p></aside>`;
const topology=()=>`<div class="topology" aria-label="Relay connects a Minecraft client to backend servers"><svg viewBox="0 0 460 220" role="img" aria-label="Client to Relay to two backends"><defs><pattern id="tiny-grid" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M8 0H0V8" fill="none" stroke="#ff2a2a" stroke-width=".5"/></pattern></defs><g fill="none" stroke="#85352f" stroke-width="1"><path d="M77 110H190M260 110h50V61h67M310 110v49h67"/><path d="M100 106l7 4-7 4m43-8 7 4-7 4m193-57 7 4-7 4m0 90 7 4-7 4" stroke="#ff2a2a"/><rect x="27" y="88" width="50" height="44" fill="#100707"/><path d="M38 100h28v17H38zM43 122h18"/><rect x="190" y="75" width="70" height="70" fill="#210b0a" stroke="#ff2a2a"/><rect x="196" y="81" width="58" height="58" fill="url(#tiny-grid)" opacity=".3"/><path d="M213 95h24v30h-24zm0 13h24M225 95v30" stroke="#ff2a2a"/><rect x="377" y="40" width="49" height="43" fill="#100707"/><rect x="377" y="138" width="49" height="43" fill="#100707"/><path d="M387 51h28m-28 10h28m-28 89h28m-28 10h28"/></g><g fill="#ad928a" font-family="JetBrains Mono,monospace" font-size="8" text-anchor="middle"><text x="52" y="155">CLIENT</text><text x="225" y="168" fill="#ff2a2a">RELAY</text><text x="402" y="101">LOBBY</text><text x="402" y="200">BACKEND</text></g></svg><span class="topology-caption">ROUTING, AT A GLANCE / 01</span></div>`;
const projectRegister=()=>`<div class="project-register"><div class="project-number">/01</div><div class="project-copy"><p class="micro">NETWORK INFRASTRUCTURE</p><h3>Relay<span style="color:var(--red)">.</span></h3><p>A Minecraft server proxy, built in Java. Connect players, route between backends, and keep your network in view.</p><div class="project-tags"><span>Java</span><span>JDK 21+</span><span>Paper backends</span></div><div class="project-links"><a href="#/docs/relay">Read the docs →</a><a href="#/api">API reference →</a>${external(source,'Source ↗')}</div></div>${topology()}</div>`;
const projectsSection=()=>`<section class="projects-section" id="projects"><div class="section-heading"><div><p class="section-label">01 / THE WORK</p><h2>Out of the void.</h2></div>${external('https://github.com/pustka-sh','All repositories ↗','text-link')}</div>${projectRegister()}<p class="under-register">Built in the open. Follow the source as it takes shape.</p></section>`;
function home(){return `<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="signal"></span>AN INDEPENDENT MINECRAFT WORKSHOP</div><h1>Minecraft.<br>From the<br><span class="red">void.</span></h1><p class="hero-description"><strong>Mods, loaders, proxies, and the ideas in between.</strong><br>A small corner of the internet for building beneath the surface. Welcome to pustka.</p><div class="hero-actions"><a class="button" href="#/projects">Explore the projects <span>↗</span></a><a class="text-link" href="#/docs/relay">Read the docs <span>→</span></a></div><p class="hero-footnote">pustka <span style="color:var(--red)">/</span> Polish, noun. Emptiness. The void.</p></div><figure class="specimen" aria-label="An original isometric voxel study with a void at its center"><div class="specimen-top"><span>VOID STUDY / 001</span><span>NOTHING → SOMETHING</span></div><svg class="specimen-canvas" id="void-specimen" viewBox="0 0 620 560" aria-hidden="true"></svg><figcaption class="specimen-controls"><span>A WORLD IS ONLY THE BEGINNING.</span><div class="control-buttons" aria-label="Illustration view"><button data-specimen="solid" aria-pressed="true">Solid</button><button data-specimen="wire" aria-pressed="false">Wireframe</button></div></figcaption></figure></section></div><div class="container scope-strip"><span><b>01</b> MODS</span><span><b>02</b> MODLOADERS</span><span><b>03</b> PROXIES</span><span><b>04</b> THE IN-BETWEEN</span><span class="strip-note">A sandbox without an edge.</span></div><div class="container">${projectsSection()}<section class="reading-section"><div><p class="section-label">02 / THE KNOWLEDGE</p><h2>Less guessing.<br>More building.</h2><p>The way in, the moving parts, and the contracts between them. Find the details that help you make something of your own.</p></div><div class="reading-links"><a class="reading-row" href="#/docs/quickstart"><span>01</span><div><h3>Get Relay running</h3><p>From the source to your first backend.</p></div><span>↗</span></a><a class="reading-row" href="#/docs/backend"><span>02</span><div><h3>Connect the pieces</h3><p>Backend messages, client mods, typed packets.</p></div><span>↗</span></a><a class="reading-row" href="#/api"><span>03</span><div><h3>Read the API</h3><p>The dashboard HTTP and WebSocket reference.</p></div><span>↗</span></a></div></section><section class="manifesto"><div class="void-symbol" aria-hidden="true"><img src="assets/pustka-mark.svg" alt="" width="70" height="70"></div><div><h2>There’s room for your kind of strange.</h2><p>A mod that changes one thing. A loader that tries another way. A piece of infrastructure nobody has built yet. It starts somewhere.</p></div>${external('https://github.com/pustka-sh','Find us on GitHub ↗','text-link')}</section></div>`;}
const docNav=[['relay','Introduction'],['quickstart','Quick start'],['backend','Backend API'],['client','Client API'],['packets','Typed packets']];
const docData={
relay:{title:'Meet Relay.',description:'One connection in. A network of possibilities.',body:`<p>Relay is pustka’s Java Minecraft proxy. It sits between players and your Paper servers, handling the connections between them.</p><h2 id="overview">A look inside</h2>${topology()}<p>Explore the project, then follow the setup guide or choose an integration below.</p><div class="doc-choices"><a href="#/docs/quickstart"><span>Get Relay running</span><span>→</span></a><a href="#/docs/backend"><span>Talk to the proxy from a backend</span><span>→</span></a><a href="#/docs/client"><span>Connect a client mod</span><span>→</span></a><a href="#/api"><span>Explore the dashboard API</span><span>→</span></a></div><h2 id="requirements">Before you begin</h2><p>You’ll need JDK 21+ and Paper backends. The repository lists support for Minecraft 1.20.2–1.21.8; check upstream for current compatibility.</p>`,source,sourceLabel:'Relay repository',toc:[['overview','A look inside'],['requirements','Before you begin']],next:['quickstart','Quick start']},
quickstart:{title:'From source to server.',description:'Bring up Relay, connect a backend, and check your setup.',body:`<h2 id="build">01 / Start from source</h2><p>Clone Relay and run its Gradle launcher. The initial launch creates <code>run/relay.toml</code> and a forwarding secret.</p>${code('git clone https://github.com/pustka-sh/Relay.git\ncd Relay\n./gradlew run')}<h2 id="backend">02 / Connect Paper</h2><p>Keep backend ports private. Set <code>online-mode=false</code> in the backend’s <code>server.properties</code>. In <code>config/paper-global.yml</code>, enable Velocity forwarding, set its online-mode to true, and use the generated secret.</p>${callout('<strong>Keep the boundary intact.</strong> Relay handles authentication. A backend configured for proxy forwarding must not be reachable directly from the internet.')}<h2 id="check">03 / Link and check</h2><p>The optional helper uses Python 3.11+. Replace the example path with your Paper directory.</p>${code('py relay.py link lobby /path/to/paper-server\npy relay.py doctor\npy relay.py run')}<p>Use the upstream guide for complete configuration and platform-specific instructions.</p>`,source:source+'#quick-start',sourceLabel:'Complete setup guide',toc:[['build','Start from source'],['backend','Connect Paper'],['check','Link and check']],previous:['relay','Introduction'],next:['backend','Backend API']},
backend:{title:'The backend connection.',description:'Let server plugins talk to the proxy using a familiar messaging contract.',body:`<h2 id="channels">Channels</h2><p>Relay accepts BungeeCord-compatible plugin messages on these channels:</p>${code('bungeecord:main\nBungeeCord\nrelay:main','plugin channels')}<p>Enable the integration with <code>backend-api = true</code>. Messages begin with a sub-channel name and use Java UTF strings and big-endian primitives.</p><h2 id="operations">Queries and actions</h2><table class="reference-table"><thead><tr><th>Type</th><th>Examples</th></tr></thead><tbody><tr><td>Read</td><td>GetServer, GetServers, PlayerCount, PlayerList</td></tr><tr><td>Route</td><td>Connect, ConnectOther</td></tr><tr><td>Interact</td><td>Message, MessageRaw, KickPlayer</td></tr></tbody></table><h2 id="boundary">The trust boundary</h2><p>Backend calls trust the server, rather than checking a player’s permissions. Keep backend ports private. These messages travel over player connections, so an empty backend cannot exchange them.</p>${callout('Need the exact fields or a plugin example? The upstream reference documents the full wire contract.')}`,source:source+'/blob/main/docs/backend-api.md',sourceLabel:'Backend wire reference',toc:[['channels','Channels'],['operations','Queries and actions'],['boundary','Trust boundary']],previous:['quickstart','Quick start'],next:['client','Client API']},
client:{title:'A conversation with the client.',description:'A small, negotiated protocol for Minecraft client mods.',body:`<h2 id="handshake">Start with a handshake</h2><p>Enable <code>client-api = true</code> and communicate on <code>relay:api_v1</code>. The client sends <code>Hello</code> before making requests. Vanilla clients receive no unsolicited API messages.</p>${code('channel   relay:api_v1\nversion   1\nencoding  VarInt message type + body','protocol identity')}<h2 id="messages">Serverbound messages</h2><table class="reference-table"><thead><tr><th>ID</th><th>Message</th><th>Purpose</th></tr></thead><tbody><tr><td>0x00</td><td>Hello</td><td>Negotiate version and identify the mod</td></tr><tr><td>0x01</td><td>List Servers</td><td>Query available destinations</td></tr><tr><td>0x02</td><td>Request Switch</td><td>Ask to move to another server</td></tr></tbody></table><h2 id="permissions">Permissions still apply</h2><p>Listing servers requires <code>relay.command.glist</code>; switching requires <code>relay.command.server</code>. Relay checks permissions on each action. Capabilities announced during negotiation help the interface, but do not authorize requests.</p>${callout('Messages are limited to 32,768 bytes and 20 messages per second. See the wire reference for field layouts and replies.')}`,source:source+'/blob/main/docs/client-api.md',sourceLabel:'Client wire reference',toc:[['handshake','Handshake'],['messages','Messages'],['permissions','Permissions']],previous:['backend','Backend API'],next:['packets','Typed packets']},
packets:{title:'Packets with a shared language.',description:'Typed application messages between your backend plugins.',body:`<h2 id="registry">Agree on the registry</h2><p><code>PacketFactory</code> builds on backend forwarding. Both ends share packet registrations; a registry fingerprint catches mismatched definitions. Serialization and deserialization must agree on field order.</p><h2 id="delivery">Choose a destination</h2><table class="reference-table"><thead><tr><th>Method</th><th>Use</th></tr></thead><tbody><tr><td>send</td><td>Send to a backend</td></tr><tr><td>sendToPlayer</td><td>Route through a player</td></tr><tr><td>broadcast</td><td>Send across backends</td></tr></tbody></table><p>Packets are limited to 32 KB and need a player connection at the sending and receiving backends. A successful local submission does not confirm remote delivery; implement a reply when you need an acknowledgement.</p><h2 id="example">See it in practice</h2><p>The ${external(source+'/tree/main/examples/block-mirror','block-mirror example ↗')} shows a working packet integration. Add registrations at the end and deploy matching definitions to both ends.</p>`,source:source+'/blob/main/docs/server-packets.md',sourceLabel:'Typed packet reference',toc:[['registry','The registry'],['delivery','Delivery'],['example','Working example']],previous:['client','Client API']}
};
const endpointData=[['GET','/api/overview','Network totals and balancing mode.'],['GET','/api/servers','Backend health, latency, population, and resource readings.'],['GET','/api/groups','Backend groups and their totals.'],['GET','/api/players','A paginated view of players and their routes.'],['WS','/api/events','A live stream of player and backend-health events.'],['GET','/api/audit','Recent network operations.'],['POST','/api/actions/{drain,send,evacuate,kick}','Permission-controlled network actions.']];
function apiContent(){return `<h2 id="dashboard">Dashboard companion</h2><p>These routes belong to a Relay dashboard running on your own network. They are not public endpoints on pustka.sh. The companion is disabled by default.</p>${callout('<strong>Access matters.</strong> Off-loopback use requires accounts. Mutating requests also check permissions and CSRF protection, and record an audit entry.')}<div class="api-tabs" role="tablist" aria-label="Endpoint category"><button role="tab" id="api-tab-all" aria-controls="endpoint-list" aria-selected="true" data-api-filter="all">All routes</button><button role="tab" id="api-tab-read" aria-controls="endpoint-list" aria-selected="false" tabindex="-1" data-api-filter="read">Read</button><button role="tab" id="api-tab-actions" aria-controls="endpoint-list" aria-selected="false" tabindex="-1" data-api-filter="actions">Actions</button></div><div id="endpoint-list" role="tabpanel" aria-labelledby="api-tab-all">${endpoints('all')}</div><h2 id="integrations">Looking for a wire protocol?</h2><div class="doc-choices"><a href="#/docs/backend"><span>Backend plugin messaging</span><span>→</span></a><a href="#/docs/client"><span>Client mod protocol</span><span>→</span></a><a href="#/docs/packets"><span>Typed server packets</span><span>→</span></a></div>`;}
function endpoints(filter){return endpointData.filter(e=>filter==='all'||(filter==='actions'?e[0]==='POST':e[0]!=='POST')).map(e=>`<details class="endpoint"><summary><span class="method ${e[0]==='POST'?'post':''}">${e[0]}</span><code>${e[1]}</code></summary><div class="endpoint-body"><p>${e[2]}</p>${e[1]==='/api/players'?'<p>Query parameters: <code>q</code>, <code>server</code>, <code>offset</code>, <code>limit</code>.</p>':''}${external(source+'#dashboard-api','Full upstream contract ↗','text-link')}</div></details>`).join('');}
function docsPage(key,isApi=false){const d=isApi?{title:'The reference layer.',description:'The interfaces between your ideas and the network.',body:apiContent(),source:source+'#dashboard-api',sourceLabel:'Upstream dashboard API',toc:[['dashboard','Dashboard companion'],['integrations','Other protocols']]}:docData[key];if(!d)return notFound();return `<div class="docs-shell"><button class="mobile-doc-nav" aria-expanded="false" aria-controls="docs-sidebar">Relay / ${isApi?'API reference':docNav.find(n=>n[0]===key)[1]} <span>Browse +</span></button><aside class="docs-sidebar" id="docs-sidebar" aria-label="Documentation navigation"><div class="docs-project">Relay <span>proxy</span></div><p class="sidebar-label">START HERE</p>${docNav.slice(0,2).map(([id,title])=>`<a href="#/docs/${id}" class="${key===id&&!isApi?'active':''}" ${key===id&&!isApi?'aria-current="page"':''}>${title}</a>`).join('')}<p class="sidebar-label">INTEGRATIONS</p>${docNav.slice(2).map(([id,title])=>`<a href="#/docs/${id}" class="${key===id&&!isApi?'active':''}" ${key===id&&!isApi?'aria-current="page"':''}>${title}</a>`).join('')}<a href="#/api" class="${isApi?'active':''}" ${isApi?'aria-current="page"':''}>Dashboard API</a><p class="sidebar-label">ELSEWHERE</p>${external(source,'Relay source ↗')}${external(source+'/issues','Issues & feedback ↗')}</aside><article class="docs-content ${isApi?'api-intro':''}"><div class="breadcrumbs"><a href="#/">pustka</a><span>/</span><a href="#/docs/relay">Relay</a><span>/</span>${isApi?'API':docNav.find(n=>n[0]===key)[1]}</div><h1>${d.title}</h1><p class="lead">${d.description}</p>${d.body}<div class="doc-source"><span>Continue at the source</span>${external(d.source,d.sourceLabel+' ↗')}</div>${!isApi?`<nav class="doc-pagination" aria-label="Adjacent documentation">${d.previous?`<a href="#/docs/${d.previous[0]}"><span><small>PREVIOUS</small>← ${d.previous[1]}</span></a>`:''}${d.next?`<a href="#/docs/${d.next[0]}"><span><small>NEXT</small>${d.next[1]} →</span></a>`:''}</nav>`:''}</article><nav class="docs-toc" aria-label="On this page"><p>ON THIS PAGE</p>${d.toc.map(t=>`<a href="#${t[0]}" data-scroll="${t[0]}">${t[1]}</a>`).join('')}</nav></div>`;}
function notFound(){return `<div class="container page-intro"><p class="section-label">404 / THE ACTUAL VOID</p><h1>Nothing here. Yet.</h1><p>That path doesn’t lead to a page.</p><a class="button" href="#/">Back to the workshop →</a></div>`;}
function render(event){const route=location.hash.replace(/^#/,'')||'/';let html,title;if(route==='/'){html=home();title='pustka — Minecraft. From the void.';}else if(route==='/projects'){html=`<div class="container projects-page"><header class="page-intro"><p class="section-label">THE PROJECT REGISTER</p><h1>Built here.<br>Open to everyone.</h1><p>A workshop for Minecraft mods, loaders, proxies, and tools. Start with the software taking shape in the open.</p></header>${projectsSection()}</div>`;title='Projects — pustka';}else if(route==='/api'){html=docsPage(null,true);title='Relay API — pustka';}else if(route.startsWith('/docs/')){const key=route.split('/')[2];html=docsPage(key);title=(docData[key]?.title||'Not found')+' — pustka';}else{html=notFound();title='The void — pustka';}$('#content').innerHTML=html;document.title=title;document.querySelectorAll('[data-nav]').forEach(a=>{const active=route.startsWith('/'+a.dataset.nav);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});window.scrollTo({top:0,left:0,behavior:'instant'});if(event)$('#content').focus({preventScroll:true});if(route==='/')window.renderSpecimen();}
window.addEventListener('hashchange',render);
document.addEventListener('click',async e=>{
 const specimen=e.target.closest('[data-specimen]');if(specimen){document.querySelectorAll('[data-specimen]').forEach(b=>b.setAttribute('aria-pressed',String(b===specimen)));window.renderSpecimen(specimen.dataset.specimen);}
 const copy=e.target.closest('.copy-button');if(copy){try{await navigator.clipboard.writeText(copy.closest('.code-block').querySelector('code').textContent);copy.textContent='Copied';toast('Copied to clipboard.');setTimeout(()=>{if(copy.isConnected)copy.textContent='Copy';},2000);}catch{toast('Select the command to copy it.');}}
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();if(scroll.dataset.scroll==='content')$('#content').focus({preventScroll:true});document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 const mobile=e.target.closest('.mobile-doc-nav');if(mobile){const open=mobile.getAttribute('aria-expanded')!=='true';mobile.setAttribute('aria-expanded',String(open));$('#docs-sidebar').classList.toggle('open',open);mobile.querySelector('span').textContent=open?'Close −':'Browse +';}
 const filter=e.target.closest('[data-api-filter]');if(filter){setApiTab(filter);}
});
function setApiTab(button){document.querySelectorAll('[data-api-filter]').forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});$('#endpoint-list').innerHTML=endpoints(button.dataset.apiFilter);$('#endpoint-list').setAttribute('aria-labelledby',button.id);}
document.addEventListener('keydown',e=>{if(e.target.matches('[data-api-filter]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-api-filter]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();setApiTab(tabs[i]);}});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2200);}
const searchIndex=[{title:'Relay',detail:'Project / Minecraft server proxy',url:'#/projects',terms:'java proxy projects'},...docNav.map(([id,title])=>({title,detail:'Relay / Documentation',url:'#/docs/'+id,terms:docData[id].description+' '+id})),{title:'Dashboard API',detail:'Relay / HTTP & WebSocket routes',url:'#/api',terms:'api endpoints players servers groups events audit actions dashboard'}];
function search(){const q=$('#site-search').value.toLowerCase().trim();const items=searchIndex.filter(d=>(d.title+' '+d.detail+' '+d.terms).toLowerCase().includes(q));$('#search-results').innerHTML=items.length?items.map(d=>`<a class="search-result" href="${d.url}"><span>${esc(d.title)}<small>${esc(d.detail)}</small></span><span>↗</span></a>`).join(''):`<p class="search-empty">No match for “${esc(q)}”. Try “Relay”, “client”, or “API”.</p>`;}
function openSearch(){const dialog=$('.search-dialog');if(dialog.open)return;dialog.showModal();$('#site-search').value='';search();$('#site-search').focus();}
$('.search-trigger').addEventListener('click',openSearch);$('#site-search').addEventListener('input',search);$('#site-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#search-results a')?.click();}});$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('.search-dialog').close();});$('.search-dialog').addEventListener('click',e=>{if(e.target===$('.search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});if(navigator.platform?.includes('Win'))$('.search-trigger kbd').textContent='Ctrl K';
render();
